interface.definition:
a!localVariables(
  local!status: "In Progress",
  local!refreshCounter: 0,
  local!data: a!refreshVariable(
    value: #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333837"(
      username: ri!cawUser.userName
    ),
    refreshOnVarChange: local!refreshCounter
  ),
  local!completedData: index(
    local!data,
    wherecontains(
      "Completed",
      touniformstring(index(local!data, "status", null))
    ),
    null
  ),
  local!inProgressData: local!completedData: index(
    local!data,
    wherecontains(
      "In Progress",
      touniformstring(index(local!data, "status", null))
    ),
    null
  ),
  {
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "Users",
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Status",
                  labelPosition: "ABOVE",
                  choiceLabels: { "Success", "In Progress" },
                  choiceValues: { "Completed", "In Progress" },
                  value: local!status,
                  saveInto: { local!status },
                  choiceLayout: "COMPACT",
                  validations: {}
                )
              },
              width: "AUTO"
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_ButtonArrayLayout"(
                  buttons: {
                    #"SYSTEM_SYSRULES_ButtonWidget"(
                      label: "Refresh",
                      saveInto: a!save(local!refreshCounter, local!refreshCounter+1),
                      style: "NORMAL"
                    )
                  },
                  align: "END",
                  marginAbove: "STANDARD"
                )
              },
              width: "AUTO"
            )

          }
        )
      }
    ),
    #"SYSTEM_SYSRULES_sectionLayout_v1"(
      label: "User Details",
      contents: {
        #"SYSTEM_SYSRULES_gridField_v1"(
          data: if(
            local!status = "In progress",
            local!inProgressData,
            local!completedData
          ),
          columns: {
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "Status",
              value: fv!row.status,
              width: "AUTO"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "First Name",
              value: fv!row.firstName,
              width: "AUTO"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "Last Name",
              value: fv!row.lastName,
              width: "AUTO"
            ),
            #"SYSTEM_SYSRULES_gridColumn"(
              label: "User Name",
              value: fv!row.UserName,
              width: "AUTO"
            )
          }
        ),
        #"SYSTEM_SYSRULES_ButtonArrayLayout"(
          buttons: #"SYSTEM_SYSRULES_ButtonWidget"(label: "OK", submit: true, style: "PRIMARY"),
          align: "END"
        )
      }
    )
  }
)
